 connect(browseWorker,&QPushButton::clicked,this,[=]{auto p=QFileDialog::getOpenFileName(this,tr("选择 Worker"));if(!p.isEmpty())d->worker->setText(p);});connect(browseData,&QPushButton::clicked,this,[=]{auto p=QFileDialog::getExistingDirectory(this,tr("选择 Geant4 数据根目录"));if(!p.isEmpty())d->data->setText(p);});connect(fit,&QPushButton::clicked,this,[=]{d->view->fit();});connect(d->run,&QPushButton::clicked,this,[=]{auto path=QDir(QStandardPaths::writableLocation(QStandardPaths::DocumentsLocation)).filePath("SpaceRad/jobs/"+QUuid::createUuid().toString(QUuid::WithoutBraces));try{runTo(path);}catch(const std::exception& e){showError(e.what());}});connect(d->cancel,&QPushButton::clicked,this,&WorkbenchWidget::cancel);
 auto changed=[this]{if(d->refreshing)return;invalidate();try{auto p=project();updateEnvironment(p);updateVoxelControls(p);auto selected=d->selectedId;d->view->setProject(p);rebuildModelTree(p);d->selectedId.clear();setProperty("selectedComponentId",QString{});bool present=false;for(int i=0;i<d->tree->topLevelItemCount();++i)present|=d->tree->topLevelItem(i)->data(0,Qt::UserRole).toString()==selected;if(present&&!selected.isEmpty())selectComponent(selected);else d->selection->setText(tr("选择模型树或剂量行可定位部件；高亮只影响显示。"));d->status->setText(tr("工程已改变，待重新计算。"));}catch(const std::exception& e){d->normalization->setText(tr("工程参数无效，当前归一化不可用：%1").arg(QString::fromUtf8(e.what())));showError(e.what());}emit projectChanged();};connect(d->volumes,&QTableWidget::cellChanged,this,[=](int,int){changed();});connect(d->histories,qOverload<int>(&QSpinBox::valueChanged),this,[=](int){changed();});for(auto* spin:{d->duration,d->radius,d->cut})connect(spin,&QLineEdit::textChanged,this,[=](const QString&){changed();});connect(d->voxelEnabled,&QCheckBox::toggled,this,[=](bool){changed();});connect(d->voxelVolume,qOverload<int>(&QComboBox::currentIndexChanged),this,[=](int){changed();});for(auto* spin:d->voxelCounts)connect(spin,qOverload<int>(&QSpinBox::valueChanged),this,[=](int){changed();});connect(d->voxelEdges,&QLineEdit::textChanged,this,[=](const QString&){changed();});connect(d->voxelMinHits,qOverload<int>(&QSpinBox::valueChanged),this,[=](int){changed();});connect(d->voxelMaxRse,qOverload<double>(&QDoubleSpinBox::valueChanged),this,[=](double){changed();});connect(d->worker,&QLineEdit::textChanged,this,[=]{if(!d->refreshing)invalidate();});connect(d->data,&QLineEdit::textChanged,this,[=]{if(!d->refreshing)invalidate();});
 connect(d->import,&QPushButton::clicked,this,[=]{auto path=QFileDialog::getOpenFileName(this,tr("导入全向微分谱 CSV"),{},"CSV (*.csv)");if(path.isEmpty())return;try{auto p=project();auto particle=d->particle->currentData().toString().toStdString();auto spectrum=spacerad::engine::loadSpectrumCsv(path,particle,false,p.quantity);p.spectra.erase(std::remove_if(p.spectra.begin(),p.spectra.end(),[&](const Spectrum& s){return s.particle==particle;}),p.spectra.end());p.spectra.push_back(spectrum);p.synthetic=std::any_of(p.spectra.begin(),p.spectra.end(),[](const Spectrum& s){return s.provenance.at("source_file").is_null();});p.environmentMetadata=engine::defaultEnvironmentMetadata();p.environmentSource="User-provided CSV with retained spectra; source bytes retained; no environment-model execution";setProject(p);d->tabs->setCurrentIndex(1);}catch(const std::exception& e){showError(e.what());}});
 connect(d->exportJson,&QPushButton::clicked,this,[=]{auto path=QFileDialog::getSaveFileName(this,tr("导出新结果文件"),{},"JSON (*.json)");if(path.isEmpty())return;try{if(d->accepted.isEmpty())throw std::runtime_error("No accepted result");saveNew(path,d->accepted);}catch(const std::exception& e){showError(e.what());}});connect(d->exportCsv,&QPushButton::clicked,this,[=]{auto path=QFileDialog::getSaveFileName(this,tr("导出新剂量表"),{},"CSV (*.csv)");if(path.isEmpty())return;try{if(d->accepted.isEmpty())throw std::runtime_error("No accepted result");auto r=Json::parse(d->accepted.toStdString());QString csv="id,mass_kg,tid_Gy,tid_standard_error_Gy,relative_standard_error,nonzero_histories\n";for(const auto& t:r.at("targets")){auto id=text(t.at("id"));id.replace('"',"\"\"");csv+='"'+id+'"';for(auto key:{"mass_kg","tid_Gy","tid_standard_error_Gy","relative_standard_error","nonzero_histories"})csv+=','+text(t.at(key).dump());csv+='\n';}saveNew(path,csv.toUtf8());}catch(const std::exception& e){showError(e.what());}});
